/* TZ-taste demo site — Builder B (data + JS)
 * Vanilla JS, no dependencies. All data comes from window.TZDATA
 * (generated by scripts/build-demo-data.mjs). No fetch calls. */
(function () {
  "use strict";

  /* ---------- small helpers ---------- */
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }
  function lc1(s) {
    s = String(s || "");
    return s ? s.charAt(0).toLowerCase() + s.slice(1) : s;
  }

  var reduceMotion = window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (reduceMotion && document.documentElement) {
    document.documentElement.classList.add("reduced");
  }

  /* ---------- toast ---------- */
  var toastEl = $("toast");
  var toastTimer = null;
  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    if (toastTimer) clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toastEl.classList.remove("show");
    }, 2200);
  }

  /* ---------- copy helper (clipboard API + textarea fallback) ---------- */
  function copyText(text, okMsg) {
    okMsg = okMsg || "Copied to clipboard";
    function done() { toast(okMsg); }
    function fallback() {
      var ta = document.createElement("textarea");
      ta.value = text;
      ta.setAttribute("readonly", "");
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand("copy"); done(); }
      catch (e) { toast("Copy failed — select the text manually"); }
      document.body.removeChild(ta);
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done, fallback);
    } else {
      fallback();
    }
  }

  /* ---------- data gate ---------- */
  var TZ = window.TZDATA;
  if (!TZ) {
    var gridIds = [
      "dna-grid", "templates-grid", "generative-grid",
      "scenes-grid", "pattern-grid", "source-table"
    ];
    gridIds.forEach(function (id) {
      var g = $(id);
      if (g) g.innerHTML = '<p class="loading error">Data failed to load.</p>';
    });
    return;
  }

  var dnaById = {};
  TZ.dnas.forEach(function (d) { dnaById[d.id] = d; });

  var NAVY = { bg: "#0e1b2c", ink: "#e8eef6", accent: "#c9a227", muted: "#8fa3bd", line: "#ffffff22", surface: "#14263c" };

  function firstDnaTokens(item) {
    if (item && item.dnas && item.dnas.length && dnaById[item.dnas[0]]) {
      return dnaById[item.dnas[0]].tokens;
    }
    return NAVY;
  }

  function cardVars(tokens) {
    return 'style="--dbg:' + esc(tokens.bg) +
      ";--dink:" + esc(tokens.ink) +
      ";--daccent:" + esc(tokens.accent) +
      ";--dmuted:" + esc(tokens.muted) +
      ";--dline:" + esc(tokens.line) + ';"';
  }

  function tokenDots(tokens) {
    var keys = ["bg", "ink", "accent", "muted"];
    return '<div class="token-dots">' + keys.map(function (k) {
      return '<i style="background:' + esc(tokens[k]) +
        '" title="' + k + " " + esc(tokens[k]) + '"></i>';
    }).join("") + "</div>";
  }

  /* ---------- hero: ambient light canvas (blueprint grid + drifting light) ---------- */
  (function heroAmbient() {
    var cv = $("hero-bg");
    if (!cv) return;
    var ctx = cv.getContext("2d");
    if (!ctx) return;
    var W = 0, H = 0, raf = 0, running = false;
    var blobs = [
      { x: .16, y: .30, r: .30, c: "0,144,193",  a: .10, ph: 0.0, sp: .00021 },
      { x: .86, y: .16, r: .26, c: "70,225,255", a: .13, ph: 2.1, sp: .00017 },
      { x: .74, y: .84, r: .32, c: "182,240,0",  a: .06, ph: 4.2, sp: .00014 },
      { x: .10, y: .86, r: .24, c: "0,144,193",  a: .08, ph: 1.3, sp: .00019 }
    ];
    var plus = [];
    for (var i = 0; i < 26; i++) {
      plus.push({ x: Math.random(), y: Math.random(), s: 5 + Math.random() * 8,
        ph: Math.random() * 6.283, sp: .00005 + Math.random() * .00008 });
    }
    function resize() {
      var dpr = Math.min(window.devicePixelRatio || 1, 1.5);
      var r = cv.getBoundingClientRect();
      W = Math.max(1, Math.round(r.width * dpr));
      H = Math.max(1, Math.round(r.height * dpr));
      cv.width = W; cv.height = H;
    }
    function frame(t) {
      ctx.clearRect(0, 0, W, H);
      var gs = Math.max(30, W / 36);
      ctx.lineWidth = 1;
      ctx.strokeStyle = "rgba(11,14,19,.055)";
      ctx.beginPath();
      var off = (t * .012) % gs;
      var x, y;
      for (x = -gs + off; x < W + gs; x += gs) { ctx.moveTo(x, 0); ctx.lineTo(x, H); }
      for (y = -gs + off; y < H + gs; y += gs) { ctx.moveTo(0, y); ctx.lineTo(W, y); }
      ctx.stroke();
      var j, b, bx, by, g;
      for (j = 0; j < blobs.length; j++) {
        b = blobs[j];
        bx = (b.x + Math.cos(t * b.sp + b.ph) * .035) * W;
        by = (b.y + Math.sin(t * b.sp * 1.3 + b.ph) * .035) * H;
        g = ctx.createRadialGradient(bx, by, 0, bx, by, b.r * Math.max(W, H));
        g.addColorStop(0, "rgba(" + b.c + "," + b.a + ")");
        g.addColorStop(1, "rgba(" + b.c + ",0)");
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, W, H);
      }
      ctx.strokeStyle = "rgba(0,119,163,.30)";
      ctx.lineWidth = 1;
      for (j = 0; j < plus.length; j++) {
        var p = plus[j];
        var py = ((p.y + t * p.sp) % 1) * H;
        var px = p.x * W + Math.sin(t * .001 + p.ph) * 9;
        var s = p.s * (.65 + .35 * Math.sin(t * .002 + p.ph));
        ctx.beginPath();
        ctx.moveTo(px - s / 2, py); ctx.lineTo(px + s / 2, py);
        ctx.moveTo(px, py - s / 2); ctx.lineTo(px, py + s / 2);
        ctx.stroke();
      }
      if (!reduceMotion) raf = requestAnimationFrame(frame);
    }
    function start() { if (!running) { running = true; raf = requestAnimationFrame(frame); } }
    function stop() { running = false; cancelAnimationFrame(raf); }
    resize();
    if (reduceMotion) { frame(4000); } else { start(); }
    window.addEventListener("resize", function () { resize(); if (reduceMotion) frame(4000); });
    document.addEventListener("visibilitychange", function () {
      if (reduceMotion) return;
      if (document.hidden) stop(); else start();
    });
  })();

  /* ---------- hero: tactical 3D viewport (hand-rolled wireframe) ---------- */
  (function tacViewport() {
    var cv = $("tac-canvas");
    if (!cv) return;
    var ctx = cv.getContext("2d");
    if (!ctx) return;
    var W = 0, H = 0, raf = 0, running = false, inView = true;
    var NEON = "70,225,255", LIME = "182,240,0", WHITE = "235,242,250";
    var D2R = Math.PI / 180;
    var lats = [], lons = [], a, k;
    for (var la = -60; la <= 60; la += 30) {
      var lp = [];
      for (a = 0; a <= 72; a++) {
        var th = a / 72 * Math.PI * 2, cl = Math.cos(la * D2R);
        lp.push([cl * Math.cos(th), Math.sin(la * D2R), cl * Math.sin(th)]);
      }
      lats.push(lp);
    }
    for (var lo = 0; lo < 12; lo++) {
      var np = [], off2 = lo * 15 * D2R;
      for (a = 0; a <= 72; a++) {
        var ph = a / 72 * Math.PI * 2;
        np.push([Math.cos(ph) * Math.cos(off2), Math.sin(ph), Math.cos(ph) * Math.sin(off2)]);
      }
      lons.push(np);
    }
    var rings = [
      { r: 1.5,  tilt: 28 * D2R,  sp: .00042,  sats: [{ a: 0,   c: LIME,  tr: [] }, { a: 2.5, c: NEON, tr: [] }] },
      { r: 1.82, tilt: -22 * D2R, sp: -.00030, sats: [{ a: 1.2, c: WHITE, tr: [] }] }
    ];
    var stars = [];
    for (var s = 0; s < 170; s++) {
      var t1 = Math.random() * Math.PI * 2, t2 = Math.acos(2 * Math.random() - 1), rr = 2.6 + Math.random() * 1.6;
      stars.push([rr * Math.sin(t2) * Math.cos(t1), rr * Math.cos(t2), rr * Math.sin(t2) * Math.sin(t1), Math.random()]);
    }
    var pings = [], lastPing = 0;
    var cam = { rx: .46, ry: 0 }, want = { rx: .46, ry: 0 };

    function tiltPt(p, tilt) {
      var c = Math.cos(tilt), s2 = Math.sin(tilt);
      return [p[0], p[1] * c - p[2] * s2, p[1] * s2 + p[2] * c];
    }
    function rotY(p, ry) {
      var c = Math.cos(ry), s2 = Math.sin(ry);
      return [p[0] * c + p[2] * s2, p[1], -p[0] * s2 + p[2] * c];
    }
    function rotX(p, rx) {
      var c = Math.cos(rx), s2 = Math.sin(rx);
      return [p[0], p[1] * c - p[2] * s2, p[1] * s2 + p[2] * c];
    }
    function xform(p, rx, ry) { return rotX(rotY(p, ry), rx); }
    function proj(p, cx, cy, sc) {
      var fl = 3.6, s = fl / (fl - p[2]);
      return [cx + p[0] * s * sc, cy + p[1] * s * sc];
    }
    function strokeGlobe(pts, rx, ry, cx, cy, sc, col, baseA) {
      ctx.strokeStyle = "rgba(" + col + "," + baseA + ")";
      ctx.lineWidth = 1;
      ctx.beginPath();
      var pen = false;
      for (var i = 0; i < pts.length; i++) {
        var q = xform(pts[i], rx, ry);
        if (q[2] < -0.12) { pen = false; continue; }
        var pr = proj(q, cx, cy, sc);
        if (!pen) { ctx.moveTo(pr[0], pr[1]); pen = true; }
        else ctx.lineTo(pr[0], pr[1]);
      }
      ctx.stroke();
    }

    function frame(t) {
      var cx = W / 2, cy = H / 2;
      var sc = Math.min(W, H) * 0.30;
      cam.rx += (want.rx - cam.rx) * .045;
      cam.ry += (want.ry - cam.ry) * .045;
      var ry = t * .00011 + cam.ry;
      var rx = cam.rx + Math.sin(t * .00023) * .035;

      ctx.fillStyle = "#05070c";
      ctx.fillRect(0, 0, W, H);

      var i, pr;
      for (i = 0; i < stars.length; i++) {
        var st = stars[i];
        var q = xform([st[0], st[1], st[2]], rx * .3, t * .00002);
        pr = proj(q, cx, cy, sc);
        var tw = .25 + .55 * Math.abs(Math.sin(t * .001 + st[3] * 9));
        ctx.fillStyle = "rgba(" + WHITE + "," + (tw * .5).toFixed(3) + ")";
        ctx.fillRect(pr[0], pr[1], 1.6, 1.6);
      }

      var gy = -1.62;
      ctx.lineWidth = 1;
      for (k = 1; k <= 4; k++) {
        ctx.strokeStyle = "rgba(" + NEON + "," + (0.20 - k * 0.035).toFixed(3) + ")";
        ctx.beginPath();
        for (a = 0; a <= 60; a++) {
          var ra = a / 60 * Math.PI * 2, rr2 = k * .42;
          pr = proj(xform([rr2 * Math.cos(ra), gy, rr2 * Math.sin(ra)], rx, ry), cx, cy, sc);
          if (a === 0) ctx.moveTo(pr[0], pr[1]); else ctx.lineTo(pr[0], pr[1]);
        }
        ctx.stroke();
      }
      var sweep = (t * .0011) % (Math.PI * 2);
      for (k = 0; k < 26; k++) {
        var sa = sweep - k * .028;
        ctx.strokeStyle = "rgba(" + LIME + "," + (.55 * (1 - k / 26)).toFixed(3) + ")";
        ctx.lineWidth = k === 0 ? 2 : 1;
        ctx.beginPath();
        var c0 = proj(xform([0, gy, 0], rx, ry), cx, cy, sc);
        var c1 = proj(xform([1.68 * Math.cos(sa), gy, 1.68 * Math.sin(sa)], rx, ry), cx, cy, sc);
        ctx.moveTo(c0[0], c0[1]); ctx.lineTo(c1[0], c1[1]);
        ctx.stroke();
      }

      for (i = 0; i < lats.length; i++) strokeGlobe(lats[i], rx, ry, cx, cy, sc, NEON, .5);
      for (i = 0; i < lons.length; i++) strokeGlobe(lons[i], rx, ry, cx, cy, sc, NEON, .32);

      var dialR = Math.min(W, H) * .44;
      ctx.strokeStyle = "rgba(" + NEON + ",.28)";
      ctx.lineWidth = 1;
      for (a = 0; a < 60; a++) {
        var da = a / 60 * Math.PI * 2 + t * .00006;
        var isLong = a % 5 === 0;
        var r1 = dialR - (isLong ? 10 : 5), r2 = dialR;
        ctx.globalAlpha = isLong ? .8 : .35;
        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(da) * r1, cy + Math.sin(da) * r1);
        ctx.lineTo(cx + Math.cos(da) * r2, cy + Math.sin(da) * r2);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;

      for (var ri = 0; ri < rings.length; ri++) {
        var ring = rings[ri];
        ctx.strokeStyle = "rgba(" + NEON + ",.22)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (a = 0; a <= 90; a++) {
          var aa = a / 90 * Math.PI * 2;
          var rp = tiltPt([ring.r * Math.cos(aa), 0, ring.r * Math.sin(aa)], ring.tilt);
          pr = proj(xform(rp, rx, ry), cx, cy, sc);
          if (a === 0) ctx.moveTo(pr[0], pr[1]); else ctx.lineTo(pr[0], pr[1]);
        }
        ctx.stroke();
        for (var si = 0; si < ring.sats.length; si++) {
          var sat = ring.sats[si];
          sat.a += ring.sp * 16;
          var sp = tiltPt([ring.r * Math.cos(sat.a), 0, ring.r * Math.sin(sat.a)], ring.tilt);
          pr = proj(xform(sp, rx, ry), cx, cy, sc);
          sat.tr.push([pr[0], pr[1]]);
          if (sat.tr.length > 16) sat.tr.shift();
          for (var ti = 0; ti < sat.tr.length; ti++) {
            var tal = ti / sat.tr.length;
            ctx.fillStyle = "rgba(" + sat.c + "," + (tal * tal * .6).toFixed(3) + ")";
            var ts = 1 + tal * 2.2;
            ctx.fillRect(sat.tr[ti][0] - ts / 2, sat.tr[ti][1] - ts / 2, ts, ts);
          }
          ctx.save();
          ctx.shadowColor = "rgba(" + sat.c + ",.9)";
          ctx.shadowBlur = 12;
          ctx.fillStyle = "rgba(" + sat.c + ",1)";
          ctx.fillRect(pr[0] - 2.5, pr[1] - 2.5, 5, 5);
          ctx.restore();
        }
      }

      if (t - lastPing > 2300) {
        lastPing = t;
        var pt1 = Math.random() * Math.PI * 2, pt2 = Math.acos(2 * Math.random() - 1);
        pings.push({ p: [Math.sin(pt2) * Math.cos(pt1), Math.cos(pt2), Math.sin(pt2) * Math.sin(pt1)], age: 0 });
        if (pings.length > 4) pings.shift();
      }
      for (i = pings.length - 1; i >= 0; i--) {
        var pg = pings[i];
        pg.age += 16;
        var pk = pg.age / 1200;
        if (pk >= 1) { pings.splice(i, 1); continue; }
        var pq = xform(pg.p, rx, ry);
        if (pq[2] < -0.05) continue;
        pr = proj(pq, cx, cy, sc);
        ctx.strokeStyle = "rgba(" + LIME + "," + ((1 - pk) * .8).toFixed(3) + ")";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(pr[0], pr[1], 4 + pk * sc * .5, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!reduceMotion) raf = requestAnimationFrame(frame);
    }

    function resize() {
      var dpr = Math.min(window.devicePixelRatio || 1, 1.75);
      var r = cv.getBoundingClientRect();
      W = Math.max(1, Math.round(r.width * dpr));
      H = Math.max(1, Math.round(r.height * dpr));
      cv.width = W; cv.height = H;
    }
    function start() { if (!running && inView && !reduceMotion) { running = true; raf = requestAnimationFrame(frame); } }
    function stop() { running = false; cancelAnimationFrame(raf); }

    var mod = cv.closest ? cv.closest(".module") : null;
    if (mod) {
      mod.addEventListener("mousemove", function (e) {
        var r = mod.getBoundingClientRect();
        var mx = (e.clientX - r.left) / r.width, my = (e.clientY - r.top) / r.height;
        want.ry = (mx - .5) * .7;
        want.rx = .46 + (my - .5) * .4;
      });
      mod.addEventListener("mouseleave", function () { want.rx = .46; want.ry = 0; });
    }
    if ("IntersectionObserver" in window) {
      new IntersectionObserver(function (es) {
        inView = es[0].isIntersecting;
        if (inView) start(); else stop();
      }, { threshold: .05 }).observe(cv);
    }

    var clockEl = $("hud-clock"), coordEl = $("hud-coords"), logEl = $("hud-log");
    var logs = ["▲ dna.sync :: 92 loaded", "▲ render.queue :: idle", "▲ uplink :: 12ms",
      "▲ patterns.index :: 219 entries", "▲ ci.watch :: passing", "▲ scenes.cache :: 50 warm"];
    var li = 0;
    function hudTick() {
      var d = new Date();
      var p2 = function (n) { return (n < 10 ? "0" : "") + n; };
      if (clockEl) clockEl.textContent = p2(d.getHours()) + ":" + p2(d.getMinutes()) + ":" + p2(d.getSeconds()) + " LOCAL";
      if (coordEl) {
        var lt = 35.6762 + Math.sin(Date.now() * .0001) * .004;
        var ln = 139.6503 + Math.cos(Date.now() * .00013) * .004;
        coordEl.innerHTML = lt.toFixed(4) + "°N&nbsp;&nbsp;" + ln.toFixed(4) + "°E";
      }
      if (logEl) { li = (li + 1) % logs.length; logEl.textContent = logs[li]; }
    }
    hudTick();
    setInterval(hudTick, 2600);

    resize();
    if (reduceMotion) { frame(4000); } else { start(); }
    window.addEventListener("resize", function () { resize(); if (reduceMotion) frame(4000); });
    document.addEventListener("visibilitychange", function () {
      if (reduceMotion) return;
      if (document.hidden) stop(); else start();
    });
  })();

  /* ---------- hero: terminal loop ---------- */
  (function terminal() {
    var el = $("term-screen");
    if (!el || !TZ) return;
    function sample(n) {
      var pool = TZ.dnas.slice(), o = [];
      while (o.length < n && pool.length) o.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
      return o;
    }
    var d = sample(6);
    var script = [
      { k: "cmd", s: "tz dna list --vibe cyberpunk" },
      { k: "out", s: "→ " + d.slice(0, 5).map(function (x) { return x.id; }).join(" · ") },
      { k: "cmd", s: "tz preview " + d[0].id + " --live" },
      { k: "ok",  s: "✓ showcase rendered · 0.42s" },
      { k: "cmd", s: "tz brief --dna " + d[1].id },
      { k: "out", s: "\"Use github.com/rawmware/TZ-taste as reference.\"" },
      { k: "dim", s: "── 92 DNAs · 219 patterns · 50 scenes indexed ──" }
    ];
    var timers = [];
    function later(fn, ms) { timers.push(setTimeout(fn, ms)); }
    function line(cls, html) {
      var div = document.createElement("div");
      div.className = ("t-line " + cls).replace(/\s+$/, "");
      div.innerHTML = html;
      el.appendChild(div);
      return div;
    }
    function run() {
      timers = [];
      el.innerHTML = "";
      var t = 600;
      script.forEach(function (st) {
        if (st.k === "cmd") {
          later(function () {
            var div = line("", '<span class="t-prompt">$ </span><span class="t-cmd"></span><span class="t-cursor"></span>');
            var cmdEl = div.querySelector(".t-cmd");
            var cur = div.querySelector(".t-cursor");
            var ci = 0;
            var iv = setInterval(function () {
              ci++;
              cmdEl.textContent = st.s.slice(0, ci);
              if (ci >= st.s.length) { clearInterval(iv); if (cur) cur.remove(); }
            }, 26);
            timers.push(iv);
          }, t);
          t += st.s.length * 26 + 460;
        } else {
          later(function () {
            line("t-" + st.k, esc(st.s));
          }, t);
          t += 560;
        }
      });
      later(function () { line("", '<span class="t-prompt">$ </span><span class="t-cursor"></span>'); }, t);
      later(run, t + 5200);
    }
    if (reduceMotion) {
      script.forEach(function (st) {
        if (st.k === "cmd") line("", '<span class="t-prompt">$ </span><span class="t-cmd">' + esc(st.s) + "</span>");
        else line("t-" + st.k, esc(st.s));
      });
    } else { run(); }
  })();

  /* ---------- hero: DNA signal cycler ---------- */
  (function signal() {
    var el = $("signal-body");
    if (!el || !TZ) return;
    function show() {
      var d = TZ.dnas[Math.floor(Math.random() * TZ.dnas.length)];
      var tags = d.tags.slice(0, 3).map(function (tg) {
        return "<span>" + esc(tg) + "</span>";
      }).join("");
      el.innerHTML =
        '<div class="sig-name">' + esc(d.name) + "</div>" +
        '<p class="sig-vibe">' + esc(d.vibe) + "</p>" +
        '<div class="sig-meta">' + tokenDots(d.tokens) +
        '<div class="dna-tags">' + tags + "</div></div>";
    }
    show();
    if (reduceMotion) return;
    setInterval(function () {
      el.classList.add("swap");
      setTimeout(function () { show(); el.classList.remove("swap"); }, 360);
    }, 3400);
  })();

  /* ---------- hero: DNA ticker ---------- */
  (function ticker() {
    var el = $("ticker-track");
    if (!el || !TZ) return;
    var half = TZ.dnas.slice(0, 30).map(function (d) {
      return "<span><b>///</b>&nbsp;" + esc(d.name) + ' <i>' + esc(d.tokens.accent) + "</i></span>";
    }).join("");
    el.innerHTML = half + half;
  })();

  /* ---------- hero: telemetry counters + sparkline ---------- */
  (function telemetry() {
    var el = $("hero-stats");
    if (!el || !TZ) return;
    var c = TZ.counts;
    var items = [
      ["dnas", "style DNAs"], ["patterns", "patterns"], ["generative", "generative"],
      ["scenes", "3D scenes"], ["templates", "templates"], ["prompts", "prompts"],
      ["languages", "languages"]
    ];
    el.innerHTML = items.map(function (p) {
      return '<div class="tele"><b data-n="' + c[p[0]] + '">0</b><span>' + p[1] + "</span></div>";
    }).join("");
    var bs = el.querySelectorAll("b");
    if (reduceMotion) {
      for (var i = 0; i < bs.length; i++) bs[i].textContent = bs[i].getAttribute("data-n");
    } else {
      var t0 = null;
      (function tick(t) {
        if (!t0) t0 = t;
        var k = Math.min(1, (t - t0) / 1500), e = 1 - Math.pow(1 - k, 3);
        for (var j = 0; j < bs.length; j++) {
          bs[j].textContent = Math.round(+bs[j].getAttribute("data-n") * e);
        }
        if (k < 1) requestAnimationFrame(tick);
      })(performance.now());
    }
    var cv = $("spark");
    if (cv) {
      var ctx = cv.getContext("2d");
      if (ctx) {
        var data = [8, 14, 12, 22, 31, 28, 44, 52, 49, 66, 78, 92];
        function draw(prog) {
          var r = cv.getBoundingClientRect();
          var dpr = Math.min(window.devicePixelRatio || 1, 2);
          var W = Math.max(1, Math.round(r.width * dpr)), H = Math.max(1, Math.round(r.height * dpr));
          if (cv.width !== W || cv.height !== H) { cv.width = W; cv.height = H; }
          ctx.clearRect(0, 0, W, H);
          var max = 100, pad = 6 * dpr;
          function px(i) { return pad + i / (data.length - 1) * (W - pad * 2); }
          function py(v) { return H - pad - v / max * (H - pad * 2); }
          var n = Math.max(2, Math.floor(data.length * prog));
          var m;
          ctx.beginPath();
          ctx.moveTo(px(0), py(0));
          for (m = 0; m < n; m++) ctx.lineTo(px(m), py(data[m]));
          ctx.lineTo(px(n - 1), py(0));
          ctx.closePath();
          var g = ctx.createLinearGradient(0, 0, 0, H);
          g.addColorStop(0, "rgba(0,144,193,.22)");
          g.addColorStop(1, "rgba(0,144,193,0)");
          ctx.fillStyle = g;
          ctx.fill();
          ctx.beginPath();
          for (m = 0; m < n; m++) { if (m === 0) ctx.moveTo(px(m), py(data[m])); else ctx.lineTo(px(m), py(data[m])); }
          ctx.strokeStyle = "#0090c1";
          ctx.lineWidth = 2 * dpr;
          ctx.lineJoin = "round";
          ctx.shadowColor = "rgba(0,144,193,.45)";
          ctx.shadowBlur = 8 * dpr;
          ctx.stroke();
          ctx.shadowBlur = 0;
          var lx = px(n - 1), ly = py(data[n - 1]);
          ctx.fillStyle = "rgba(182,240,0,.25)";
          ctx.beginPath(); ctx.arc(lx, ly, 8 * dpr, 0, Math.PI * 2); ctx.fill();
          ctx.fillStyle = "#9fd400";
          ctx.beginPath(); ctx.arc(lx, ly, 3.5 * dpr, 0, Math.PI * 2); ctx.fill();
        }
        if (reduceMotion) { draw(1); }
        else {
          var s0 = null;
          (function anim(t) {
            if (!s0) s0 = t;
            var k = Math.min(1, (t - s0) / 1600);
            draw(k);
            if (k < 1) requestAnimationFrame(anim);
          })(performance.now());
        }
        window.addEventListener("resize", function () { draw(1); });
      }
    }
  })();

  /* ---------- modal (shared) ---------- */
  var modal = $("tz-modal"),
      mTitle = $("tz-modal-title"),
      mClose = $("tz-modal-close"),
      mLoading = $("tz-modal-loading"),
      mFrame = $("tz-modal-frame"),
      mMeta = $("tz-modal-meta"),
      mActions = $("tz-modal-actions");
  var lastOpener = null;

  function openModal(opts) {
    if (!modal) return;
    lastOpener = document.activeElement;
    mTitle.textContent = opts.title || "";
    mMeta.innerHTML = opts.metaHTML || "";
    mActions.innerHTML = "";
    (opts.actions || []).forEach(function (a) {
      if (a.href) {
        var link = document.createElement("a");
        link.className = "btn-line";
        link.textContent = a.label;
        link.href = a.href;
        link.target = "_blank";
        link.rel = "noopener";
        mActions.appendChild(link);
      } else if (a.copy) {
        var btn = document.createElement("button");
        btn.className = "btn-line";
        btn.type = "button";
        btn.textContent = a.label;
        btn.addEventListener("click", function () {
          copyText(a.copy, a.copiedMsg || "Copied to clipboard");
        });
        mActions.appendChild(btn);
      }
    });
    if (mLoading) mLoading.style.display = "";
    if (mFrame && opts.iframeFile) {
      var onLoad = function () {
        if (mLoading) mLoading.style.display = "none";
        mFrame.removeEventListener("load", onLoad);
      };
      mFrame.addEventListener("load", onLoad);
      mFrame.src = opts.iframeFile; // lazy: only on open — page now served from repo root, paths are site-relative
    } else if (mFrame) {
      mFrame.removeAttribute("src");
      if (mLoading) mLoading.style.display = "none";
    }
    modal.classList.add("open");
    modal.removeAttribute("hidden");
    document.body.classList.add("modal-open");
    if (mClose) mClose.focus();
  }

  function closeModal() {
    if (!modal) return;
    if (mFrame) mFrame.removeAttribute("src");
    modal.classList.remove("open");
    modal.setAttribute("hidden", "");
    document.body.classList.remove("modal-open");
    if (lastOpener && lastOpener.focus) {
      try { lastOpener.focus(); } catch (e) { /* noop */ }
    }
    lastOpener = null;
  }

  if (modal) {
    if (mClose) mClose.addEventListener("click", closeModal);
    modal.addEventListener("click", function (e) {
      if (e.target === modal) closeModal();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && modal.classList.contains("open")) closeModal();
    });
  }

  function cssVarsText(tokens) {
    return ":root{" +
      "--tz-bg:" + tokens.bg + ";" +
      "--tz-ink:" + tokens.ink + ";" +
      "--tz-accent:" + tokens.accent + ";" +
      "--tz-muted:" + tokens.muted + ";" +
      "--tz-line:" + tokens.line + ";" +
      "--tz-surface:" + (tokens.surface || tokens.bg) + ";}";
  }

  function tailwindBlock(dna) {
    var t = dna.tokens, f = dna.fonts;
    function q(s) { return '"' + String(s).replace(/"/g, '\\"') + '"'; }
    return "module.exports = {\n" +
      "  theme: {\n" +
      "    extend: {\n" +
      "      colors: {\n" +
      '        "tz-bg": ' + q(t.bg) + ",\n" +
      '        "tz-ink": ' + q(t.ink) + ",\n" +
      '        "tz-accent": ' + q(t.accent) + ",\n" +
      '        "tz-muted": ' + q(t.muted) + ",\n" +
      '        "tz-line": ' + q(t.line) + ",\n" +
      '        "tz-surface": ' + q(t.surface || t.bg) + ",\n" +
      "      },\n" +
      "      fontFamily: {\n" +
      "        display: [" + q(f.display) + "],\n" +
      "        body: [" + q(f.body) + "],\n" +
      "        mono: [" + q(f.mono) + "],\n" +
      "      },\n" +
      "    },\n" +
      "  },\n" +
      "};";
  }

  function openDnaModal(dna) {
    var t = dna.tokens;
    var rows = ["bg", "ink", "accent", "muted", "line", "surface"].map(function (k) {
      var v = t[k] || t.bg;
      return "<tr><td>" + k + '</td><td><code>' + esc(v) + "</code></td>" +
        '<td><i class="tok-swatch" style="background:' + esc(v) + '"></i></td></tr>';
    }).join("");
    var fonts = dna.fonts;
    var dials = dna.dials;
    var meta =
      '<table class="tok-table"><thead><tr><th>Token</th><th>Hex</th><th></th></tr></thead>' +
      "<tbody>" + rows + "</tbody></table>" +
      '<p class="m-fonts">Fonts — display <b>' + esc(fonts.display) + "</b> · body <b>" +
      esc(fonts.body) + "</b> · mono <b>" + esc(fonts.mono) + "</b></p>" +
      '<p class="m-dials">Dials — density ' + dials.density + "/10 · motion " +
      dials.motion + "/10 · variance " + dials.variance + "/10</p>" +
      '<p class="m-best">Best for: ' +
      dna.best_for.map(function (b) { return "<span>" + esc(b) + "</span>"; }).join(", ") +
      "</p>";
    openModal({
      title: dna.name,
      metaHTML: meta,
      iframeFile: dna.showcase,
      actions: [
        { label: "Open showcase page", href: dna.showcase },
        { label: "Copy tokens as CSS", copy: cssVarsText(t) },
        { label: "Copy Tailwind preset", copy: tailwindBlock(dna) }
      ]
    });
  }

  /* ---------- DNA wall ---------- */
  var dnaGrid = $("dna-grid");
  var activeTag = "All";
  var dnaQuery = "";

  function dnaCardHTML(d) {
    return '<article class="dna-card" data-dna-id="' + esc(d.id) + '" ' +
      cardVars(d.tokens) + ' tabindex="0" role="button" aria-label="' + esc(d.name) + '">' +
      "<h3>" + esc(d.name) + "</h3>" +
      '<p class="vibe">' + esc(d.vibe) + "</p>" +
      tokenDots(d.tokens) +
      '<div class="dna-tags">' +
      d.tags.slice(0, 3).map(function (tg) {
        return "<span>" + esc(tg) + "</span>";
      }).join("") + "</div></article>";
  }

  function renderDnaWall() {
    if (!dnaGrid) return;
    var q = dnaQuery.trim().toLowerCase();
    var list = TZ.dnas.filter(function (d) {
      if (activeTag !== "All" && d.tags.indexOf(activeTag) === -1) return false;
      if (!q) return true;
      var hay = (d.name + " " + d.vibe + " " + d.tags.join(" ")).toLowerCase();
      return hay.indexOf(q) !== -1;
    });
    dnaGrid.innerHTML = list.map(dnaCardHTML).join("") ||
      '<p class="loading">No DNAs match.</p>';
  }

  (function initDnaWall() {
    renderDnaWall();
    var search = $("dna-search");
    if (search) {
      search.addEventListener("input", function () {
        dnaQuery = search.value;
        renderDnaWall();
      });
    }
    var tf = $("tag-filters");
    if (tf) {
      var counts = {};
      TZ.dnas.forEach(function (d) {
        d.tags.forEach(function (t) { counts[t] = (counts[t] || 0) + 1; });
      });
      var top = Object.keys(counts)
        .sort(function (a, b) { return counts[b] - counts[a]; })
        .slice(0, 12);
      tf.innerHTML = ["All"].concat(top).map(function (t) {
        return '<button type="button" class="chip' + (t === "All" ? " active" : "") +
          '" data-tag="' + esc(t) + '">' + esc(t) + "</button>";
      }).join("");
      tf.addEventListener("click", function (e) {
        var b = e.target.closest ? e.target.closest(".chip") : null;
        if (!b) return;
        activeTag = b.getAttribute("data-tag");
        var chips = tf.querySelectorAll(".chip");
        for (var i = 0; i < chips.length; i++) {
          chips[i].classList.toggle("active", chips[i] === b);
        }
        renderDnaWall();
      });
    }
    if (dnaGrid) {
      dnaGrid.addEventListener("click", function (e) {
        var card = e.target.closest ? e.target.closest(".dna-card") : null;
        if (!card) return;
        var dna = dnaById[card.getAttribute("data-dna-id")];
        if (dna) openDnaModal(dna);
      });
      dnaGrid.addEventListener("keydown", function (e) {
        if (e.key !== "Enter" && e.key !== " ") return;
        var card = e.target.closest ? e.target.closest(".dna-card") : null;
        if (!card) return;
        e.preventDefault();
        var dna = dnaById[card.getAttribute("data-dna-id")];
        if (dna) openDnaModal(dna);
      });
    }
  })();

  function flashDnaCard(dnaId) {
    var card = document.querySelector('#dna-grid [data-dna-id="' + dnaId + '"]');
    if (!card) {
      // card may be hidden by an active filter — reset filters so it shows
      activeTag = "All";
      dnaQuery = "";
      var s = $("dna-search");
      if (s) s.value = "";
      renderDnaWall();
      card = document.querySelector('#dna-grid [data-dna-id="' + dnaId + '"]');
    }
    if (!card) return;
    card.scrollIntoView({ behavior: reduceMotion ? "auto" : "smooth", block: "center" });
    card.classList.add("flash");
    setTimeout(function () { card.classList.remove("flash"); }, 2000);
  }

  /* ---------- templates / generative / scenes ---------- */
  function dnaNameOf(item) {
    return (item.dnas && item.dnas.length && dnaById[item.dnas[0]])
      ? dnaById[item.dnas[0]].name : "Various";
  }

  function cardAttrs(item) {
    return ' data-file="' + esc(item.file) +
      '" data-title="' + esc(item.title) +
      '" data-desc="' + esc(item.description || "") +
      '" tabindex="0" role="button" aria-label="' + esc(item.title) + '"';
  }

  function tplCardHTML(item) {
    return '<article class="tpl-card"' + cardAttrs(item) + ">" +
      '<div class="browser-thumb"' + cardVars(firstDnaTokens(item)) + ">" +
      '<div class="tb-chrome"><i></i><i></i><i></i><span class="tb-url"></span></div>' +
      '<div class="tb-art"><span class="tb-bar"></span></div></div>' +
      '<div class="tpl-body"><h3>' + esc(item.title) + "</h3>" +
      '<p class="desc">' + esc(item.description || "") + "</p>" +
      '<p class="dna-line">DNA: ' + esc(dnaNameOf(item)) + "</p></div></article>";
  }

  function genCardHTML(item) {
    var tag = (item.tags && item.tags[0]) || "generative";
    return '<article class="gen-card"' + cardAttrs(item) + ">" +
      '<div class="gen-thumb" aria-hidden="true"></div>' +
      '<div class="gen-body"><h3>' + esc(item.title) + "</h3>" +
      "<p>" + esc(item.description || "") + "</p>" +
      '<span class="tech-tag">' + esc(tag) + "</span></div></article>";
  }

  function sceneCardHTML(item, i) {
    var n = ("0" + (i + 1)).slice(-2);
    return '<article class="scene-card"' + cardAttrs(item) + ">" +
      '<div class="scene-thumb" aria-hidden="true"></div>' +
      '<div class="scene-body"><p class="scene-no">Scene ' + n + " / " +
      TZ.scenes.length + "</p><h3>" + esc(item.title) + "</h3>" +
      "<p>" + esc(item.description || "") + "</p></div></article>";
  }

  function wireItemGrid(gridId, items, render) {
    var grid = $(gridId);
    if (!grid) return;
    grid.innerHTML = items.map(function (it, i) { return render(it, i); }).join("");
    function open(e) {
      var card = e.target && e.target.closest ? e.target.closest("article") : null;
      if (!card) return;
      openModal({
        title: card.getAttribute("data-title"),
        metaHTML: '<p class="desc">' + esc(card.getAttribute("data-desc")) + "</p>",
        iframeFile: card.getAttribute("data-file"),
        actions: [{ label: "Open standalone", href: card.getAttribute("data-file") }]
      });
    }
    grid.addEventListener("click", open);
    grid.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); open(e); }
    });
  }

  wireItemGrid("templates-grid", TZ.templates, tplCardHTML);
  wireItemGrid("generative-grid", TZ.generative, genCardHTML);
  wireItemGrid("scenes-grid", TZ.scenes, sceneCardHTML);

  /* ---------- patterns ---------- */
  (function initPatterns() {
    var grid = $("pattern-grid");
    if (!grid) return;
    var patQuery = "";
    var patCat = "All";

    function rowHTML(p) {
      return '<article class="pat-row" data-file="' + esc(p.file) +
        '" data-title="' + esc(p.title) +
        '" tabindex="0" role="button" aria-label="' + esc(p.title) + '">' +
        '<span class="pat-cat">' + esc(p.category || "") + "</span>" +
        "<h3>" + esc(p.title) + "</h3>" +
        '<p class="desc">' + esc(p.description || "") + "</p>" +
        '<span class="pat-preview" aria-hidden="true">Preview</span></article>';
    }

    function render() {
      var q = patQuery.trim().toLowerCase();
      var list = TZ.patterns.filter(function (p) {
        if (patCat !== "All" && p.category !== patCat) return false;
        if (!q) return true;
        var hay = (p.title + " " + (p.description || "") + " " +
          (p.tags || []).join(" ")).toLowerCase();
        return hay.indexOf(q) !== -1;
      });
      grid.innerHTML = list.map(rowHTML).join("") ||
        '<p class="loading">No patterns match.</p>';
    }

    var search = $("pattern-search");
    if (search) {
      search.addEventListener("input", function () {
        patQuery = search.value;
        render();
      });
    }

    var catEl = $("pattern-cat");
    if (catEl) {
      var cats = {};
      TZ.patterns.forEach(function (p) { cats[p.category || "Misc"] = 1; });
      var names = ["All"].concat(Object.keys(cats).sort());
      if (catEl.tagName === "SELECT") {
        catEl.innerHTML = names.map(function (c) {
          return '<option value="' + esc(c) + '">' + esc(c) + "</option>";
        }).join("");
        catEl.addEventListener("change", function () {
          patCat = catEl.value;
          render();
        });
      } else {
        catEl.innerHTML = names.map(function (c) {
          return '<button type="button" class="chip' + (c === "All" ? " active" : "") +
            '" data-cat="' + esc(c) + '">' + esc(c) + "</button>";
        }).join("");
        catEl.addEventListener("click", function (e) {
          var b = e.target.closest ? e.target.closest(".chip") : null;
          if (!b) return;
          patCat = b.getAttribute("data-cat");
          var chips = catEl.querySelectorAll(".chip");
          for (var i = 0; i < chips.length; i++) {
            chips[i].classList.toggle("active", chips[i] === b);
          }
          render();
        });
      }
    }

    function open(e) {
      var row = e.target && e.target.closest ? e.target.closest(".pat-row") : null;
      if (!row) return;
      var file = row.getAttribute("data-file");
      openModal({
        title: row.getAttribute("data-title"),
        metaHTML: '<p class="hint">Copy-paste snippet — open the file, copy the ' +
          "&lt;style&gt; + markup.</p>" +
          '<p class="repo-path"><code>' + esc(file) + "</code></p>",
        iframeFile: file,
        actions: [
          { label: "Open standalone", href: file },
          { label: "Copy file path", copy: file, copiedMsg: "File path copied" }
        ]
      });
    }
    grid.addEventListener("click", open);
    grid.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") { e.preventDefault(); open(e); }
    });
    render();
  })();

  /* ---------- token exporter ---------- */
  (function initExporter() {
    var sel = $("export-dna");
    if (!sel) return;
    var cssPre = $("export-css"), twPre = $("export-tw"), jsonPre = $("export-json");

    sel.innerHTML = TZ.dnas.map(function (d) {
      return '<option value="' + esc(d.id) + '">' + esc(d.name) + "</option>";
    }).join("");

    function render() {
      var dna = dnaById[sel.value] || TZ.dnas[0];
      if (!dna) return;
      var t = dna.tokens, f = dna.fonts;
      if (cssPre) {
        cssPre.textContent =
          "/* " + dna.name + " — TZ-taste DNA */\n" +
          "/* Display: " + f.display + " · Body: " + f.body + " · Mono: " + f.mono + " */\n" +
          ":root{\n" +
          "  --tz-bg: " + t.bg + ";\n" +
          "  --tz-ink: " + t.ink + ";\n" +
          "  --tz-accent: " + t.accent + ";\n" +
          "  --tz-muted: " + t.muted + ";\n" +
          "  --tz-line: " + t.line + ";\n" +
          "  --tz-surface: " + (t.surface || t.bg) + ";\n" +
          "}";
      }
      if (twPre) twPre.textContent = tailwindBlock(dna);
      if (jsonPre) jsonPre.textContent = JSON.stringify(t, null, 2);
    }
    sel.addEventListener("change", render);
    render();
  })();

  /* ---------- delegated copy buttons (data-copy-target) ---------- */
  document.addEventListener("click", function (e) {
    var b = e.target && e.target.closest ?
      e.target.closest("[data-copy-target]") : null;
    if (!b) return;
    var pre = $(b.getAttribute("data-copy-target"));
    if (!pre) return;
    copyText(pre.textContent || "", "Copied to clipboard");
  });

  /* ---------- prompt builder ---------- */
  (function initPromptBuilder() {
    var dnaSel = $("pb-dna"), typeSel = $("pb-type"), toneSel = $("pb-tone"),
        output = $("pb-output"), copyBtn = $("pb-copy");
    if (!dnaSel || !output) return;

    dnaSel.innerHTML = TZ.dnas.map(function (d) {
      return '<option value="' + esc(d.id) + '">' + esc(d.name) + "</option>";
    }).join("");

    function build() {
      var dna = dnaById[dnaSel.value] || TZ.dnas[0];
      var type = typeSel && typeSel.selectedOptions && typeSel.selectedOptions[0]
        ? typeSel.selectedOptions[0].textContent.trim() : "page";
      var tone = toneSel && toneSel.selectedOptions && toneSel.selectedOptions[0]
        ? toneSel.selectedOptions[0].textContent.trim() : "confident";
      var f = dna.fonts;
      output.textContent =
        "Use https://github.com/rawmware/TZ-taste as a reference to build: " +
        "[a " + lc1(type) + " with " + lc1(tone) + " tone]. " +
        "Follow its AGENT.md protocol and pick the " + dna.name +
        " style DNA before writing any code.\n\n" +
        "Design rules: one DNA only — all colors resolve to its tokens " +
        "(--tz-bg/ink/accent/muted/line); real Google Fonts pairing " +
        "(" + f.display + "/" + f.body + "/" + f.mono + "); " +
        "real copy, never lorem; no purple/blue gradients; no emoji icons; " +
        "no three-equal-card grids; responsive 1440/768/390; " +
        "prefers-reduced-motion; WCAG AA contrast. " +
        "Run docs/ANTI-SLOP.md as the self-review step before delivering.";
    }

    dnaSel.addEventListener("change", build);
    if (typeSel) typeSel.addEventListener("change", build);
    if (toneSel) toneSel.addEventListener("change", build);
    if (copyBtn) copyBtn.addEventListener("click", function () {
      copyText(output.textContent || "", "Prompt copied");
    });
    build(); // on load
  })();

  /* ---------- agent-brief nav buttons ---------- */
  (function initAgentBrief() {
    var text = "Use https://github.com/rawmware/TZ-taste as a reference to build: " +
      "[your brief]. Follow its AGENT.md protocol and pick one style DNA " +
      "before writing any code.";
    document.addEventListener("click", function (e) {
      var b = e.target && e.target.closest ?
        e.target.closest('[data-copy="agent-brief"]') : null;
      if (!b) return;
      copyText(text, "Agent brief copied");
    });
  })();

  /* ---------- sources ---------- */
  (function initSources() {
    var table = $("source-table");
    if (table) {
      table.innerHTML = TZ.sources.map(function (s) {
        return '<div class="source-row">' +
          '<span class="source-name"><a href="' + esc(s.url) + '" target="_blank" rel="noopener">' +
          esc(s.name) + "</a></span>" +
          '<span class="source-what">' + esc(s.what || "") + "</span>" +
          '<span class="license-tag">' + esc(s.license || "") + "</span></div>";
      }).join("");
    }
    var note = $("freshness-note");
    if (note) {
      note.textContent = TZ.counts.sources +
        " curated sources · licenses verified · freshness CI runs weekly.";
    }
  })();


  /* ---------- scroll reveal ---------- */
  (function reveal() {
    if (!("IntersectionObserver" in window) || reduceMotion) return;
    var els = document.querySelectorAll(
      ".ticket-head,.dna-card,.tpl-card,.gen-card,.scene-card,.pat-row," +
      ".tool-panel,.source-row,.agentkit-inner,.brief-box,.kit-links");
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (e) {
        if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
      });
    }, { threshold: .06, rootMargin: "0px 0px -5% 0px" });
    Array.prototype.forEach.call(els, function (el, i) {
      el.classList.add("reveal");
      el.style.transitionDelay = ((i % 8) * 45) + "ms";
      io.observe(el);
    });
  })();

})();
